import socket
from sshuttle.helpers import Fatal


def family_to_string(family):
    if family == socket.AF_INET6:
        return "AF_INET6"
    elif family == socket.AF_INET:
        return "AF_INET"
    else:
        return str(family)


def get_socket_ip(sock):
    """Return the IP address bound to a socket."""
    return sock.getsockname()[0]


def is_ipv6(ip):
    """Check if the given IP string is IPv6."""
    return ':' in ip


def validate_ip(ip, family):
    """Validate that an IP address matches the expected address family."""
    if family == socket.AF_INET6:
        if not is_ipv6(ip):
            raise Fatal("Expected IPv6 address, got '%s'" % ip)
    else:
        if is_ipv6(ip):
            raise Fatal("Expected IPv4 address, got '%s'" % ip)
